import java.sql.*;
import java.util.*;

import javax.sql.DataSource;

import org.h2.jdbcx.JdbcDataSource;

public class Main {
    public static void main(String[] args) throws SQLException {
        DataSource ds = Database.buat();
        try (Connection c = ds.getConnection();
             Statement st = c.createStatement()) {
            st.executeUpdate("INSERT INTO todo (judul) VALUES ('A'), ('B')");
            c.setAutoCommit(false);
            st.executeUpdate("DELETE FROM todo");
            try (Connection lain = ds.getConnection();
                 Statement st2 = lain.createStatement();
                 ResultSet rs = st2.executeQuery("SELECT COUNT(*) FROM todo")) {
                rs.next();
                System.out.println("Dilihat koneksi lain sebelum commit: " + rs.getInt(1));
            }
            c.commit();
            try (ResultSet rs = st.executeQuery("SELECT COUNT(*) FROM todo")) {
                rs.next();
                System.out.println("Setelah commit: " + rs.getInt(1));
            }
        }
    }
}

